pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address target, address[] memory tos, uint[] memory values) public {
        vm.assume(tos.length > 0);
        vm.assume(tos.length == values.length);
        vm.assume(from != address(0) && from != address(this) && from != address(c));
        vm.assume(target != address(0) && target != address(this) && target != address(c));
        // Deploy adversarial callee that always returns true on call
        SuccessCallee helper = new SuccessCallee();
        bool returnedTrue;
        try c.transfer(from, address(helper), tos, values) returns (bool result) {
            returnedTrue = result;
        } catch {
            // If it reverts, test passes (no return value difference)
            assertTrue(true);
            return;
        }
        assertTrue(returnedTrue, "return value must be true when call completes");
    }
}

contract SuccessCallee {
    fallback() external payable returns (bytes memory) {
        // Return success (no revert)
        return abi.encode(true);
    }
}

